import React, { useState, useRef, useEffect } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import { useLocation } from "react-router-dom";
import Navbar from "./Navbar";
import html2canvas from "html2canvas";
import * as faceapi from "face-api.js";

function Register() {
  const location = useLocation();

  const eventId = location.state?.eventId || "";
  const eventName = location.state?.eventName || "No Event Selected";

  const [formData, setFormData] = useState({
    name: "",
    college_name: "",
    phone: "",
    email: "",
    event_id: eventId,
  });

  const [showQR, setShowQR] = useState(false);
  const [qrData, setQrData] = useState("");
  const [userId, setUserId] = useState("");
  const [photo, setPhoto] = useState("");

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const idCardRef = useRef(null);
  const streamRef = useRef(null);

  /* FACE MODEL */
  useEffect(() => {
    const loadModels = async () => {
      const MODEL_URL = "/models";
      await faceapi.nets.tinyFaceDetector.loadFromUri(MODEL_URL);
    };
    loadModels();
  }, []);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  /* ================= SHOW UPI QR ================= */
  const handlePayment = (e) => {
    e.preventDefault();
    setShowQR(true);
  };

  /* ================= REGISTER ================= */
  const confirmPayment = async () => {
    try {
      const res = await axios.post("http://localhost:5000/register", formData);

      if (res.data.success) {
        setUserId(res.data.userId);
        setQrData(res.data.qrData);
        alert("✅ Payment Verified & Registered");
      }
    } catch {
      alert("❌ Registration failed");
    }
  };

  /* ================= CAMERA ================= */
  const openCamera = async () => {
    const stream = await navigator.mediaDevices.getUserMedia({ video: true });
    streamRef.current = stream;
    videoRef.current.srcObject = stream;
    videoRef.current.play();
  };

  const capturePhoto = async () => {
    const detections = await faceapi.detectAllFaces(
      videoRef.current,
      new faceapi.TinyFaceDetectorOptions()
    );

    if (detections.length !== 1) {
      return alert("❌ Ensure only one face");
    }

    const canvas = canvasRef.current;
    canvas.width = videoRef.current.videoWidth;
    canvas.height = videoRef.current.videoHeight;

    canvas.getContext("2d").drawImage(videoRef.current, 0, 0);
    setPhoto(canvas.toDataURL());

    streamRef.current.getTracks().forEach((t) => t.stop());
  };

  /* ================= DOWNLOAD ================= */
  const downloadCard = () => {
    html2canvas(idCardRef.current).then((canvas) => {
      const link = document.createElement("a");
      link.download = "ID_Card.png";
      link.href = canvas.toDataURL();
      link.click();
    });
  };

  /* ================= UPI QR STRING ================= */
  const upiString = `arunsekar664@okaxis`;

  /* ================= STYLES ================= */
  const glass = {
    backdropFilter: "blur(15px)",
    background: "rgba(255,255,255,0.08)",
    padding: "20px",
    borderRadius: "15px",
    width: "320px",
    margin: "auto",
    display: "flex",
    flexDirection: "column",
    gap: "12px",
  };

  const input = {
    padding: "10px",
    borderRadius: "8px",
    border: "none",
  };

  const btn = {
    padding: "10px",
    borderRadius: "20px",
    background: "#ff758c",
    color: "white",
    border: "none",
    cursor: "pointer",
  };

  return (
    <div style={{ minHeight: "100vh", background: "#141e30", color: "white" }}>
      <Navbar />

      <div style={{ textAlign: "center", padding: "30px" }}>
        <h2>🚀 Event Registration</h2>

        {/* FORM */}
        {!showQR && !qrData && (
          <form style={glass} onSubmit={handlePayment}>
            <input style={input} name="name" placeholder="Name" onChange={handleChange} required />
            <input style={input} name="college_name" placeholder="College" onChange={handleChange} required />
            <input style={input} name="phone" placeholder="Phone" onChange={handleChange} required />
            <input style={input} name="email" placeholder="Email" onChange={handleChange} required />

            <h3>{eventName}</h3>

            <button style={btn}>Proceed to Pay</button>
          </form>
        )}

        {/* UPI QR */}
        {showQR && !qrData && (
          <div style={glass}>
            <h3>📲 Scan & Pay</h3>
            <QRCode value={upiString} size={200} />

            <p>Pay ₹100 via GPay / PhonePe</p>

            <button style={btn} onClick={confirmPayment}>
              I Have Paid ✅
            </button>
          </div>
        )}

        {/* QR GENERATED */}
        {qrData && !photo && (
          <div style={glass}>
            <h3>Your Entry QR</h3>
            <QRCode value={qrData} size={180} />

            <button style={btn} onClick={openCamera}>
              Capture Photo
            </button>

            <video ref={videoRef} style={{ width: "100%" }} />
            <button style={btn} onClick={capturePhoto}>Capture</button>
            <canvas ref={canvasRef} style={{ display: "none" }} />
          </div>
        )}

        {/* ID CARD */}
        {photo && (
          <div style={{ marginTop: "30px" }}>
            <div
              ref={idCardRef}
              style={{
                background: "white",
                color: "black",
                padding: "20px",
                borderRadius: "15px",
                width: "260px",
                margin: "auto",
                boxShadow: "0 10px 30px rgba(0,0,0,0.4)",
              }}
            >
              <h3>🎫 EVENT PASS</h3>
              <p>{formData.name}</p>
              <p>ID: {userId}</p>
              <p>{eventName}</p>

              <QRCode value={qrData} size={100} />
              <img src={photo} alt="" style={{ width: "100px", marginTop: "10px" }} />
            </div>

            <button style={{ ...btn, marginTop: "15px" }} onClick={downloadCard}>
              Download ID Card
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

export default Register;
